import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
total = 0
for i in range(n):
    for j in range(n):
        if i == j:
            continue
        x, y = a[i], a[j]
        if (x < 100 and y < 100) or (x > 100 and y > 100) or (x > 100 and 2 * y >= x + 14):
            total += 1
print(total)

